// ② 앞만
public class CheckAdvice implements MethodBeforeAdvice {
    public void before(Method method, Object[] args, Object target) {
        log.info("들어간다 {}", method.getName());
    }
}

// ③ 뒤만
public class DoneAdvice implements AfterReturningAdvice {
    public void afterReturning(Object returnValue, Method method,
                               Object[] args, Object target) {
        log.info("나왔다 {} -> {}", method.getName(), returnValue);
    }
}

